{
  "schemaVersion": 1,
  "id": "origins",
  "version": "${version}",

  "name": "Origins",
  "description": "This mod adds several origins with passive abilities to the game, which you can choose from at the beginning of the game.",
  "authors": [
    "Apace"
  ],
  "contact": {
    "homepage": "https://www.curseforge.com/minecraft/mc-mods/origins",
    "sources": "https://github.com/apace100/origins-fabric",
    "issues": "https://github.com/apace100/origins-fabric/issues"
  },

  "license": "MIT",
  "icon": "assets/origins/icon.png",

  "environment": "*",
  "entrypoints": {
    "main": [
      "io.github.apace100.origins.Origins"
    ],
    "client": [
      "io.github.apace100.origins.OriginsClient"
    ],
    "modmenu": [
      "io.github.apace100.origins.integration.ModMenuIntegration"
    ],
    "cardinal-components-entity": [
      "io.github.apace100.origins.registry.ModComponents"
    ],
    "calio:ordered-resource-listener": [
      "io.github.apace100.origins.Origins"
    ]
  },
  "mixins": [
    "origins.mixins.json"
  ],
  "custom": {
    "cardinal-components": [
      "origins:origin"
    ]
  },

  "depends": {
    "java": ">=17",
    "fabricloader": ">=0.15.10",
    "fabric-api": ">=0.91.6",
    "minecraft": "1.20.2",
    "apoli": ">=2.11.11",
    "calio": ">=1.13.3",
    "playerabilitylib": ">=1.9.0",
    "cardinal-components-base": ">=3.0.0",
    "cardinal-components-entity": ">=3.0.0",
    "cloth-config2": ">=5.0.0"
  },
  "breaks": {
    "optifabric": "<=1.11.18",
    "identity": "<1.14.2-beta"
  }
}

{
  "schemaVersion": 1,
  "id": "apoli",
  "version": "${version}",

  "name": "Apoli",
  "description": "A library mod which allows entities to be imbued with data-driven powers.",
  "authors": [
    "Apace"
  ],
  "contact": {
    "homepage": "https://apace100.github.io/apoli",
    "sources": "https://github.com/apace100/apoli"
  },

  "license": "MIT",
  "icon": "assets/apoli/icon.png",

  "environment": "*",
  "entrypoints": {
    "main": [
      "io.github.apace100.apoli.Apoli"
    ],
    "client": [
      "io.github.apace100.apoli.ApoliClient"
    ],
    "server": [
      "io.github.apace100.apoli.ApoliServer"
    ],
    "cardinal-components-entity": [
      "io.github.apace100.apoli.Apoli"
    ],
    "modmenu": [
      "io.github.apace100.apoli.integration.ModMenuIntegration"
    ],
    "calio:ordered-resource-listener": [
      "io.github.apace100.apoli.Apoli"
    ]
  },
  "mixins": [
    "apoli.mixins.json"
  ],
  "custom": {
    "cardinal-components": [
      "apoli:powers"
    ],
    "modmenu": {
      "badges": ["library"]
    },
    "lithium:options": {
      "mixin.entity.collisions.suffocation": false
    }
  },

  "accessWidener": "apoli.accesswidener",

  "depends": {
    "java": ">=17",
    "fabricloader": ">=0.15.10",
    "fabric-api": ">=0.91.6",
    "minecraft": "1.20.2",
    "calio": ">=1.13.3"
  }
}
